class Interval {
    int start, end;
    Interval(int start, int end) { this.start = start; this.end = end; }
    public String toString() { return "[" + start + "," + end + "]"; }
}

List<Interval> intervals = new ArrayList<>(List.of(
    new Interval(1, 3), new Interval(2, 6), new Interval(8, 10), new Interval(15, 18)
));
intervals.sort(Comparator.comparingInt(i -> i.start));

List<Interval> merged = new ArrayList<>();
for (Interval current : intervals) {
    if (!merged.isEmpty() && current.start <= merged.get(merged.size() - 1).end) {
        merged.get(merged.size() - 1).end = Math.max(merged.get(merged.size() - 1).end, current.end);
    } else {
        merged.add(current);
    }
}
System.out.println("Po scaleniu: " + merged);

class Player {
    String name; int wins, losses, score;
    Player(String name, int wins, int losses, int score) { this.name = name; this.wins = wins; this.losses = losses; this.score = score; }
    String getName() { return name; } int getScore() { return score; }
    double winRatio() { return (wins + losses == 0) ? 0.0 : (double) wins / (wins + losses); }
    public String toString() { return name + "[score=" + score + ", ratio=" + String.format("%.2f", winRatio()) + "]"; }
}

